\label{thm:strong}
Let $m$ and $n$ be positive integers. If $3\le m\le n-3$, then 
$${n\brackm}
       \frac{1-q}{(1-q^n)(1-q^{n+1})}\ge_q0.$$

\label{lem:kernel}
Let $a$ and $b$ be positive integers. For every integer $k\in [0,\ ab/2]$, we have
\begin{eqnarray}\label{formal+kernel}
 \dim_{\mathbb Q}\ker\bigl(\mathcal D:V_{b,k}\longrightarrow V_{b,k-1}\bigr)
 &=&[q^k](1-q)\mathcal G_{a,b}(q).
\end{eqnarray}
In particular, $\mathcal G_{a,b}(q)$ is unimodal.

The inner product $\langle\cdot,\cdot\rangle$ on $V_{b,k}$ makes $\mathcal E$ adjoint to $\mathcal D$, i.e.,
\begin{eqnarray}\label{inner+product+adjoint}
\langle\mathcal D f,g\rangle=\langle f,\mathcal E g\rangle
\end{eqnarray}
for all $f,g$ in $V_{b,k}$.

To obtain this identity, we will assign positive
weights to the monomial basis. Let $\textbf{x}^{\boldsymbol{\alpha}}\in V_{b,k}$ be an arbitrary monomial with $\alpha_i>0$
for $1\le i\le a$. And assume that
$\boldsymbol{\beta}=\boldsymbol{\alpha}-\boldsymbol{e}_i+\boldsymbol{e}_{i-1}$, where $\boldsymbol{e}_i$ is the coordinate
vector corresponding to $x_i$. Then in terms of the definition of the inner product $\langle\cdot,\cdot\rangle$, we obtain
\begin{eqnarray}\label{form+two+vectors}
\frac{\|\textbf{x}^{\boldsymbol{\beta}}\|^2}{\|\textbf{x}^{\boldsymbol{\alpha}}\|^2}
 =\frac{\alpha_{i-1}+1}{\alpha_i}\frac{a-i+1}{i},
\end{eqnarray}
In addition, it follows from the definitions of the operator $\mathcal D$ and the inner product $\langle\cdot,\cdot\rangle$ that
\begin{eqnarray}
\langle\mathcal D \textbf{x}^{\boldsymbol{\alpha}},\textbf{x}^{\boldsymbol{\beta}}\rangle
 &=&i\,\alpha_i\,\|\textbf{x}^{\boldsymbol{\beta}}\|^2,\label{inner+product+adjoint+1}\\
 \langle \textbf{x}^{\boldsymbol{\alpha}},\mathcal E \textbf{x}^{\boldsymbol{\beta}}\rangle
 &=&(a-i+1)(\alpha_{i-1}+1)\,\|\textbf{x}^{\boldsymbol{\alpha}}\|^2.\label{inner+product+adjoint+2}
\end{eqnarray}
Thus, by (\ref{form+two+vectors})-(\ref{inner+product+adjoint+2}), we obtain
\begin{eqnarray}
\langle\mathcal D \textbf{x}^{\boldsymbol{\alpha}},\textbf{x}^{\boldsymbol{\beta}}\rangle
 &=& \langle \textbf{x}^{\boldsymbol{\alpha}},\mathcal E \textbf{x}^{\boldsymbol{\beta}}\rangle
\end{eqnarray}
for any $\textbf{x}^{\boldsymbol{\alpha}}\in V_{b,k}$ with all $\alpha_i>0$ and $\boldsymbol{\beta}=\boldsymbol{\alpha}-\boldsymbol{e}_j+\boldsymbol{e}_{j-1}$, where $\boldsymbol{e}_j$ is the coordinate
vector corresponding to $x_j$. In addition, for any pair of monomials not related in this way, their inner
product is zero. Therefore, using the bilinearity of the inner product gives the identity (\ref{inner+product+adjoint}) for all $f,g$ in $V_{b,k}$. This prove this claim.

\label{lem:root-evaluation}
Let $A,B$ and $r$ be positive integers satisfying $A\ge B$, $r>1$ and $r|B$.
If $\zeta\in\mathbb C$ be a primitive $r$th root of unity, then
\[
  \left.{A-1\brackB-1}\right|_{q\rightarrow\zeta}
  =\begin{cases}
     0,&r\nmid A,\\[2pt]
     \displaystyle\binom{A/r-1}{B/r-1},&r\mid A.
   \end{cases}
\]

For each $d\mid r$ and $d>1$, let
\begin{eqnarray}
 &R_d(q)&:=\left.\begin{bmatrix}n/d-1\\ m/d-1\end{bmatrix}\right|_{q\rightarrow q^d},\label{def+Rd}\\
  &R(q)&:=-\sum_{\substack{d>1,\,d\mid r}}\mu(d)R_d(q),\quad S(q):=-\sum_{\substack{d>1 ,d\mid r}}\mu(d)q^{L_d}R_d(q),\label{def+R}\\
   &Q(q)&:=\frac{P(q)-[n+1]_{q}R(q)}{[m]_{q}},\quad W(q):=\frac{R(q)-S(q)}{1-q^m},\quad\quad
\end{eqnarray}

\label{lem:polynomiality}
For each $d\mid r$ and $d>1$, then we have
\begin{itemize}
\item [\rm (i)]$Q(q)\in\mathbb Z[q]$ and $\deg Q(q)\leq\delta-m+1$;
\item [\rm (ii)]
$W(q)\in\mathbb Z[q]$ and  $q^{\delta-n-m}W(q^{-1})=W(q).$
\end{itemize}

Recall (\ref{eq:G-to-R+Q}) that
\begin{eqnarray}\label{def+Gnm}
  G_{n,m}(q)  =\frac{R(q)}{1-q^m}+\frac{Q(q)}{1-q^{n+1}}.
\end{eqnarray}
Because $\frac{1}{1-q^m}\ge_q0$, the condition $R(q)\ge_q0$ implies $\frac{R(q)}{1-q^m}\ge_q0$. So by (\ref{def+Gnm}), in order to prove
$G_{n,m}(q)\ge_q0$, it suffices to show $Q(q)\ge_q0$.

In terms of the definition of $Q(q)$, we can rewrite
\begin{eqnarray}\label{expres+Q}
  Q(q)=\frac{(1-q)P(q)}{1-q^m}-\frac{(1-q^{n+1})R(q)}{1-q^m}.
\end{eqnarray}
Let $Q(q)=\sum_{k\geq0}Q_kq^k$. Expanding the denominator in (\ref{expres+Q}) as a formal power series gives
\begin{eqnarray}\label{expres+Qk}
 Q_k=\sum_{j\ge0}
  \bigl(C_{k-jm}-R_{k-jm}+R_{k-n-1-jm}\bigr)
\end{eqnarray}
for $k\geq0$. By Lemma \ref{lem:polynomiality} (i), we have $\deg Q\le\delta-m+1$.
We will prove $Q_k\geq0$ for $0\le k\le\delta-m+1$ in terms of the following two cases:

\textbf{Case 1}: $0\le k\le(\delta-m+1)/2$. We have $k\leq \delta/2$. It follows from the condition $C_k\ge r_k$ for $0\le k\le\delta/2$ and $R_k\geq0$ for $k\geq0$ that
\begin{eqnarray}
 Q_k=\sum_{j\ge0}
  \left(C_{k-jm}-R_{k-jm}\right)+\sum_{j\ge0}R_{k-n-1-jm}\geq0.
\end{eqnarray}

\textbf{Case 2}: $(\delta-m+1)/2\leq k\le \delta-m+1$.
Using
$q^\delta P(q^{-1})=P(q)$,
  $[n+1]_{q^{-1}}=q^{-n}[n+1]_q$ and
  $[m]_{q^{-1}}=q^{1-m}[m]_q$,
we obtain
\begin{eqnarray}
  q^{\delta-m+1}Q(q^{-1})
  &=&\frac{P(q)-[n+1]_{q}q^{\delta-n}R(q^{-1})}{[m]_{q}}\\
  &=&\frac{P(q)-[n+1]_{q}S(q)}{[m]_{q}},\\
   &=&\frac{(1-q)P(q)}{1-q^m}-\frac{R(q)}{1-q^m}
  +W(q)+\frac{q^{n+1}S(q)}{1-q^m},\label{eq:reduction-Q-reflection}
\end{eqnarray}
which is a polynomial because
$\deg Q\le\delta-m+1$. Let $S(q)=\sum_kS_kq^k$, whose coefficients are
those of $R(q)$ in reverse order by (\ref{symmery+R}). So $R_k\geq0$ implies $S_k\geq0$ for $k\geq0$.

Taking coefficients of $q^k$ in (\ref{eq:reduction-Q-reflection}) yields
\begin{eqnarray}
 Q_{\delta-m+1-k}
 &=&\sum_{j\ge0}(C_{k-jm}-R_{k-jm})+[q^k]W(q)+\sum_{j\ge0}S_{k-n-1-jm},
\end{eqnarray}
which is nonnegative for $0\le k\le(\delta-m+1)/2$ in terms of $C_k\ge R_k$, $W(q)\ge_q0$ and
$S(q)\ge_q0$.
Let $k'=\delta-m+1-k$. We immediately have $(\delta-m+1)/2\leq k'\le \delta-m+1$ for $0\le k\le(\delta-m+1)/2$.
In consequence, we obtain $ Q_{k'}\geq0$ for $(\delta-m+1)/2\leq k'\le \delta-m+1$.

Combining this two cases gives $Q_k\geq0$ for $0\le k\le\delta-m+1$. Hence $G_{n,m}(q)\ge_q0$. This completes the proof.

\label{lem:multiplicity}
Let $\lambda\in\mathcal P$ be nonempty and $s$ be the
number of distinct prime divisors of $H(\lambda)$. We have
\begin{itemize}
\item [\rm (i)]If $M(\lambda)\ne0$, then $H(\lambda)>1$ and its smallest
 prime divisor $p$ satisfies $\ell(\lambda)\le m/p-1$;
\item [\rm (ii)]If $M(\lambda)\ge2$ or $M(\lambda)<0$, then $H(\lambda)$
 has a second-smallest
 prime divisor $\phi$, and $\ell(\lambda)\le m/\phi-1$;
\item [\rm (iii)] If $s\le3$, then $M(\lambda)\ge0$;
\item [\rm (iv)]
If $s\ge1$, then $M(\lambda)\le2^{s-1}$. If $M(\lambda)=-c<0$,
 then $c\le2^{s-1}-1$.
\end{itemize}

\label{prop:domination}
If $m\ne6$, then we have
$ C_k\ge R_k$ for $0\le k\le\delta/2$.

Fix $i\in[2, M(\lambda)]$ and let $h=h_i(\lambda)$ and $\nu=T_h(\lambda)$ as in
\eqref{eq:partition-split}. Then there exists a $v_{\lambda,i}
 \in V_{m-1,wt(\lambda)}\cap\ker\mathcal D.$

\label{prop:domination+m6+2+3}
If $m=6$ and $r\in\{2,3\}$, then
$ C_k\ge R_k$ for $0\le k\le\delta/2.$

\label{thm:KOH}
Let $a\ge b\ge2$ be integers. For $\lambda\vdash b$, set
$ Y_j=\sum_{i=1}^j\lambda_i$ for $j\ge0.$
Then
\begin{equation}\label{eq:KOH}
 {a+b\brackb}
 =\sum_{\lambda\vdash b}
 q^{2\sum_{i\ge1}\binom{\lambda_i}{2}}
 \prod_{j=1}^{\ell(\lambda)}
 {j(a+2)-Y_{j-1}-Y_{j+1}\brack\lambda_j-\lambda_{j+1}}
\end{equation}
and every nonzero summand is symmetric and unimodal
about $ab/2$.

\label{prop:domination+m6+12}
Let$ n\geq 12$, $6\mid n$ and $r=\gcd(n,6)>1$.
Then $C_k\ge R_k$ for $0\le k\le5(n-6)/2$.

\label{prop:W-positive}
Let $n,m\in\mathbb Z$ satisfy $3\le m\le n/2$ and $r=\gcd(n,m)>1$.
Then $W(q)\ge_q0$.

\label{lem:coprime}
Let $n$ and $m$ be integers with $0<m<n$ and $\gcd(n,m)=1$.
Then $G_{n,m}(q)\ge_q0$.

For $m=1$, by (\ref{def+Fnm+Gnm}), we have
$G_{n,1}(q)=1/(1-q^{n+1})$, whose coefficients are obviously nonnegative.
Suppose $m>1$. By
$P(q)={n-1\brackm-1}$, we define a rational function
\begin{eqnarray}
 B(q)=\frac{P(q)}{[m]_{q}}.
\end{eqnarray}
It follows from (\ref{def+Fnm+Gnm}) that
\begin{eqnarray}
  G_{n,m}(q)=\frac{B(q)}{1-q^{n+1}}.
\end{eqnarray}

So, in order to prove that $G_{n,m}(q)\ge_q0$, it suffices to show $B(q)\ge_q0$. In what follows we will prove that $B(q)$ is a polynomial with only nonnegative coefficients.

If $\zeta^m=1$ and $\zeta\ne1$, then the condition $\gcd(n,m)=1$ implies that the order of $\zeta$ divides
$m$ but not $n$. By Lemma~\ref{lem:root-evaluation},
$P(\zeta)=0$. These roots are precisely simple of $[m]_{q}$.
Thus we obtain $[m]_{q}\mid P(q)$ and $B(q)\in\mathbb Z[q]$.


Easy computations give $B(0)=1$,
\begin{eqnarray}
 \deg B(q)=(m-1)(n-m-1)\ge0,
 \qquad q^{\deg B(q)}B(q^{-1})=B(q).
\end{eqnarray}
Thus, in order to prove that all coefficients of $B(q)$ are nonnegative, we only need to show that $[q^k]B(q)$ is nonnegative for $0\le k\le\deg B(q)/2$.
Since $[m]_{q}=(1-q^m)/(1-q)$, we have
\begin{eqnarray}\label{coeff+B}
[q^k]B(q)=[q^k]\frac{(1-q)P(q)}{1-q^m}
 =\sum_{j\ge0}[q^{k-jm}](1-q)P(q)
\end{eqnarray}
for $k\ge0$.
For $0\le k\le\deg B(q)/2$, each nonnegative index in this sum satisfies
\begin{eqnarray}
 0\le k-jm\le k\le\frac{\deg B(q)}{2}
 \le\frac{(m-1)(n-m)}{2}=\frac{\deg P(q)}{2}.
\end{eqnarray}

Hence, applying Lemma~\ref{lem:kernel} with $a=n-m$ and $b=m-1$ to (\ref{coeff+B}) yields nonnegativity of each term. So $[q^k]B(q)$ is nonnegative for $0\le k\le\deg B(q)/2$. We complete the proof.
